SELECT
       (
           SELECT COUNT(*)
           FROM TB_COMM_POST P
           WHERE P.USR_ID = #{usrId}
             AND P.POST_STAT = #{postActive}
       ) AS postCount
    ,  (
           SELECT COUNT(*)
           FROM TB_COMM_FOLLOW F
           WHERE F.FOLLOWING_USR_ID = #{usrId}
             AND F.FOLLOW_STAT = #{followAccepted}
       ) AS followerCount
    ,  (
           SELECT COUNT(*)
           FROM TB_COMM_FOLLOW F
           WHERE F.FOLLOWER_USR_ID = #{usrId}
             AND F.FOLLOW_STAT = #{followAccepted}
       ) AS followingCount

SELECT COUNT(*)
FROM TB_USR
WHERE USR_ID = #{usrId}

mapper.delete:
DELETE FROM TB_COMM_FOLLOW
WHERE FOLLOWER_USR_ID = #{usrId}
  AND FOLLOWING_USR_ID = #{followingUsrId}

DELETE FROM TB_COMM_FOLLOW
WHERE FOLLOWER_USR_ID = #{followerUsrId}
  AND FOLLOWING_USR_ID = #{usrId}

mapper.select:
SELECT U.USR_ID AS usrId
     , U.NCK_NM AS usrNm
     , U.PRFL_IMG_FIL_SEQ AS profileImageFilSeq
     , (SELECT COUNT(*) FROM TB_COMM_POST P WHERE P.USR_ID = U.USR_ID AND P.POST_STAT = #{postActive}) AS postCount
     , EXISTS (
           SELECT 1
           FROM TB_COMM_FOLLOW F
           WHERE F.FOLLOWER_USR_ID = #{usrId}
             AND F.FOLLOWING_USR_ID = U.USR_ID
             AND F.FOLLOW_STAT = #{followAccepted}
       ) AS following
FROM TB_USR U
WHERE U.USR_ID <> #{usrId}
  AND (
      U.NCK_NM ILIKE '%' || #{query} || '%'
      OR U.USR_NM ILIKE '%' || #{query} || '%'
  )
  AND (
      #{userFilter} = 'discover'
      OR (
          #{userFilter} = 'following'
          AND EXISTS (
              SELECT 1
              FROM TB_COMM_FOLLOW F
              WHERE F.FOLLOWER_USR_ID = #{usrId}
                AND F.FOLLOWING_USR_ID = U.USR_ID
                AND F.FOLLOW_STAT = #{followAccepted}
          )
      )
      OR (
          #{userFilter} = 'followers'
          AND EXISTS (
              SELECT 1
              FROM TB_COMM_FOLLOW F
              WHERE F.FOLLOWING_USR_ID = #{usrId}
                AND F.FOLLOWER_USR_ID = U.USR_ID
                AND F.FOLLOW_STAT = #{followAccepted}
          )
      )
  )
ORDER BY U.NCK_NM, U.USR_ID
LIMIT #{limit}

SELECT P.POST_SEQ AS postSeq
     , P.USR_ID AS authorId
     , U.NCK_NM AS authorName
     , U.PRFL_IMG_FIL_SEQ AS profileImageFilSeq
     , P.POST_CN AS content
     , TO_CHAR(P.POST_DTM, 'YYYY-MM-DD"T"HH24:MI:SS') AS createdAt
     , (SELECT COUNT(*) FROM TB_COMM_POST_LIKE L WHERE L.POST_SEQ = P.POST_SEQ) AS likeCount
     , (SELECT COUNT(*) FROM TB_COMM_CMT C WHERE C.POST_SEQ = P.POST_SEQ AND C.CMT_STAT = 'ACTIVE') AS commentCount
     , EXISTS (
           SELECT 1
           FROM TB_COMM_POST_LIKE L
           WHERE L.POST_SEQ = P.POST_SEQ
             AND L.USR_ID = #{usrId}
       ) AS likedByMe
     , EXISTS (
           SELECT 1
           FROM TB_COMM_POST_SAVE S
           WHERE S.POST_SEQ = P.POST_SEQ
             AND S.USR_ID = #{usrId}
       ) AS savedByMe
FROM TB_COMM_POST P
JOIN TB_USR U ON U.USR_ID = P.USR_ID
WHERE P.POST_STAT = #{postActive}
  AND (
      COALESCE(P.POST_TTL, '') ILIKE '%' || #{query} || '%'
      OR P.POST_CN ILIKE '%' || #{query} || '%'
      OR P.USR_ID ILIKE '%' || #{query} || '%'
      OR U.NCK_NM ILIKE '%' || #{query} || '%'
  )
  AND (
      P.VIS_TYP = #{publicVisibility}
      OR P.USR_ID = #{usrId}
      OR EXISTS (
          SELECT 1
          FROM TB_COMM_FOLLOW F
          WHERE F.FOLLOWER_USR_ID = #{usrId}
            AND F.FOLLOWING_USR_ID = P.USR_ID
            AND F.FOLLOW_STAT = #{followAccepted}
      )
  )
ORDER BY P.POST_DTM DESC
LIMIT #{limit}

SELECT
       P.POST_SEQ AS postSeq
    ,  P.USR_ID AS authorId
    ,  U.NCK_NM AS authorName
    ,  U.PRFL_IMG_FIL_SEQ AS profileImageFilSeq
    ,  P.POST_CN AS content
    ,  to_char(P.POST_DTM, 'YYYY-MM-DD"T"HH24:MI:SS') AS createdAt
    ,  (
        SELECT COUNT(*)
        FROM TB_COMM_POST_LIKE L
        WHERE L.POST_SEQ = P.POST_SEQ
    ) AS likeCount
    ,  (
        SELECT COUNT(*)
        FROM TB_COMM_CMT C
        WHERE C.POST_SEQ = P.POST_SEQ
          AND C.CMT_STAT = 'ACTIVE'
    ) AS commentCount
    ,  EXISTS (
        SELECT 1
        FROM TB_COMM_POST_LIKE L
        WHERE L.POST_SEQ = P.POST_SEQ
          AND L.USR_ID = #{usrId}
    ) AS likedByMe
    ,  EXISTS (
        SELECT 1
        FROM TB_COMM_POST_SAVE S
        WHERE S.POST_SEQ = P.POST_SEQ
          AND S.USR_ID = #{usrId}
    ) AS savedByMe
FROM TB_COMM_POST P
JOIN TB_USR U ON U.USR_ID = P.USR_ID
WHERE P.POST_STAT = #{postActive}
  AND (
      (#{feedType} = 'mine' AND P.USR_ID = #{usrId})
      OR (
          #{feedType} = 'profile'
          AND P.USR_ID = #{profileUsrId}
          AND (
              P.VIS_TYP = #{publicVisibility}
              OR P.USR_ID = #{usrId}
              OR EXISTS (
                  SELECT 1
                  FROM TB_COMM_FOLLOW F
                  WHERE F.FOLLOWER_USR_ID = #{usrId}
                    AND F.FOLLOWING_USR_ID = P.USR_ID
                    AND F.FOLLOW_STAT = #{followAccepted}
              )
          )
      )
      OR (
          #{feedType} = 'saved'
          AND EXISTS (
              SELECT 1
              FROM TB_COMM_POST_SAVE S
              WHERE S.POST_SEQ = P.POST_SEQ
                AND S.USR_ID = #{usrId}
          )
          AND (
              P.VIS_TYP = #{publicVisibility}
              OR P.USR_ID = #{usrId}
              OR EXISTS (
                  SELECT 1
                  FROM TB_COMM_FOLLOW F
                  WHERE F.FOLLOWER_USR_ID = #{usrId}
                    AND F.FOLLOWING_USR_ID = P.USR_ID
                    AND F.FOLLOW_STAT = #{followAccepted}
              )
          )
      )
      OR (
          #{feedType} NOT IN ('mine', 'saved', 'profile')
          AND (
              P.VIS_TYP = #{publicVisibility}
              OR P.USR_ID = #{usrId}
              OR EXISTS (
                  SELECT 1
                  FROM TB_COMM_FOLLOW F
                  WHERE F.FOLLOWER_USR_ID = #{usrId}
                    AND F.FOLLOWING_USR_ID = P.USR_ID
                    AND F.FOLLOW_STAT = #{followAccepted}
              )
          )
      )
  )
  AND (
      #{feedType} IN ('mine', 'saved', 'profile')
      OR NOT EXISTS (
          SELECT 1
          FROM TB_COMM_POST_SEEN V
          WHERE V.POST_SEQ = P.POST_SEQ
            AND V.USR_ID = #{usrId}
      )
  )
  AND (
      #{feedType} <> 'following'
      OR EXISTS (
          SELECT 1
          FROM TB_COMM_FOLLOW F
          WHERE F.FOLLOWER_USR_ID = #{usrId}
            AND F.FOLLOWING_USR_ID = P.USR_ID
            AND F.FOLLOW_STAT = #{followAccepted}
      )
  )
ORDER BY
    CASE
        WHEN #{feedType} IN ('mine', 'popular', 'saved') THEN 0
        WHEN EXISTS (
            SELECT 1
            FROM TB_COMM_FOLLOW F
            WHERE F.FOLLOWER_USR_ID = #{usrId}
              AND F.FOLLOWING_USR_ID = P.USR_ID
              AND F.FOLLOW_STAT = #{followAccepted}
        ) THEN 0
        ELSE 1
    END,
    CASE
        WHEN #{feedType} = 'popular' THEN (
            SELECT COUNT(*)
            FROM TB_COMM_POST_LIKE L
            WHERE L.POST_SEQ = P.POST_SEQ
        )
        ELSE 0
    END DESC,
    P.POST_DTM DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM TB_COMM_POST P
WHERE P.POST_SEQ = #{postSeq}
  AND P.POST_STAT = #{postActive}
  AND (
      P.VIS_TYP = #{publicVisibility}
      OR P.USR_ID = #{usrId}
      OR EXISTS (
          SELECT 1
          FROM TB_COMM_FOLLOW F
          WHERE F.FOLLOWER_USR_ID = #{usrId}
            AND F.FOLLOWING_USR_ID = P.USR_ID
            AND F.FOLLOW_STAT = #{followAccepted}
      )
  )

SELECT COUNT(*)
FROM TB_COMM_CMT
WHERE POST_SEQ = #{postSeq}
  AND CMT_SEQ = #{cmtSeq}
  AND CMT_STAT = 'ACTIVE'

WITH RANKED_COMMENTS AS ( SELECT C.POST_SEQ AS postSeq , C.CMT_SEQ AS cmtSeq , C.PARENT_CMT_SEQ AS parentCmtSeq , C.USR_ID AS usrId , U.NCK_NM AS usrNm , U.PRFL_IMG_FIL_SEQ AS profileImageFilSeq , C.CMT_CN AS cmtCn , TO_CHAR(C.CMT_DTM, 'YYYY-MM-DD"T"HH24:MI:SS') AS cmtDtm , ROW_NUMBER() OVER ( PARTITION BY C.POST_SEQ ORDER BY C.CMT_DTM DESC ) AS rowNum FROM TB_COMM_CMT C JOIN TB_USR U ON U.USR_ID = C.USR_ID JOIN TB_COMM_POST P ON P.POST_SEQ = C.POST_SEQ WHERE C.CMT_STAT = 'ACTIVE' AND P.POST_STAT = #{postActive} AND P.POST_SEQ IN
#{postSeq}
AND C.PARENT_CMT_SEQ IS NULL AND ( P.VIS_TYP = #{publicVisibility} OR P.USR_ID = #{usrId} OR EXISTS ( SELECT 1 FROM TB_COMM_FOLLOW F WHERE F.FOLLOWER_USR_ID = #{usrId} AND F.FOLLOWING_USR_ID = P.USR_ID AND F.FOLLOW_STAT = #{followAccepted} ) ) ) SELECT postSeq , cmtSeq , parentCmtSeq , usrId , usrNm , profileImageFilSeq , cmtCn , cmtDtm FROM RANKED_COMMENTS WHERE rowNum <= 2 ORDER BY postSeq, rowNum DESC

mapper.insert:
INSERT INTO TB_COMM_CMT (
    POST_SEQ
    ,  USR_ID
    ,  PARENT_CMT_SEQ
    ,  CMT_CN
    ,  CMT_STAT
    ,  CMT_DTM
    ,  FRST_REG_USER_ID
)
VALUES (
    #{command.postSeq}
    ,  #{command.usrId}
    ,  #{command.parentCmtSeq}
    ,  #{command.commentContent}
    ,  'ACTIVE'
    ,  CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul'
    ,  #{command.frstRegUserId}
)

mapper.update:
UPDATE TB_COMM_CMT
   SET CMT_CN = #{command.commentContent}
    ,  LAST_MOD_USER_ID = #{command.userId}
    ,  LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
WHERE CMT_SEQ = #{command.cmtSeq}
  AND POST_SEQ = #{command.postSeq}
  AND USR_ID = #{command.usrId}
  AND CMT_STAT = 'ACTIVE'

UPDATE TB_COMM_CMT
   SET CMT_STAT = 'DELETED'
    ,  LAST_MOD_USER_ID = #{command.usrId}
    ,  LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
WHERE CMT_SEQ = #{command.cmtSeq}
  AND POST_SEQ = #{command.postSeq}
  AND USR_ID = #{command.usrId}
  AND CMT_STAT = 'ACTIVE'

