mapper.select:
SELECT
       (
           SELECT COUNT(*)
           FROM TB_COMM_POST_FILE PF
           JOIN TB_COMM_POST P ON P.POST_SEQ = PF.POST_SEQ
           WHERE PF.FIL_SEQ = #{filSeq}
             AND P.POST_STAT = #{postActive}
             AND (
                 P.VIS_TYP = #{publicVisibility}
                 OR P.USR_ID = #{usrId}
                 OR EXISTS (
                     SELECT 1
                     FROM TB_COMM_FOLLOW F
                     WHERE F.FOLLOWER_USR_ID = #{usrId}
                       AND F.FOLLOWING_USR_ID = P.USR_ID
                       AND F.FOLLOW_STAT = #{followAccepted}
                 )
             )
       )
    +  (
           SELECT COUNT(*)
           FROM TB_USR U
           WHERE U.PRFL_IMG_FIL_SEQ = #{filSeq}
       )
